#include "model_import.hpp"
#include "mod_appearance.hpp"
#include <iostream>
using namespace livery;
namespace im=livery::importer;
static Bytes fixture(Json node=Json::object(),bool badIndex=false){
 Bytes bin;for(auto p:std::vector<im::P>{{-1,0,-2},{1,0,-2},{0,1,2}})for(double x:p)im::putFloat(bin,x);for(unsigned i:{0u,1u,badIndex?8u:2u})put16(bin,i);bin.resize(44);
 Json d={{"asset",{{"version","2.0"}}},{"buffers",Json::array({{{"byteLength",44}}})},{"bufferViews",Json::array({{{"buffer",0},{"byteOffset",0},{"byteLength",36}},{{"buffer",0},{"byteOffset",36},{"byteLength",6}}})},{"accessors",Json::array({{{"bufferView",0},{"componentType",5126},{"count",3},{"type","VEC3"}},{{"bufferView",1},{"componentType",5123},{"count",3},{"type","SCALAR"}}})},{"meshes",Json::array({{{"primitives",Json::array({{{"attributes",{{"POSITION",0}}},{"indices",1}}})}}})},{"scenes",Json::array({{{"nodes",Json::array({0})}}})},{"scene",0}};node["mesh"]=0;d["nodes"]=Json::array({node});auto j=d.dump();while(j.size()%4)j+=' ';Bytes bytes;put32(bytes,0x46546c67);put32(bytes,2);put32(bytes,12+8+j.size()+8+bin.size());put32(bytes,j.size());put32(bytes,0x4e4f534a);append(bytes,j);put32(bytes,bin.size());put32(bytes,0x004e4942);bytes.insert(bytes.end(),bin.begin(),bin.end());return bytes;
}
template<class F>static void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}require(failed,"Invalid input was accepted");}
int main(int argc,char**argv){try{
 auto basic=im::readGLB(fixture());require(basic.triangles==1&&basic.parts[0].uv.size()==3,"Basic GLB failed");auto translated=im::readGLB(fixture({{"translation",{5,2,3}},{"scale",{2,1,1}}}));require(translated.parts[0].positions[0]==im::P{3,2,1},"TRS transform failed");auto mirrored=im::readGLB(fixture({{"scale",{-1,1,1}}}));require(mirrored.parts[0].indices==std::vector<uint32_t>({0,2,1}),"Mirrored winding failed");rejects([]{im::readGLB(fixture({},true));});rejects([]{im::readGLB(fixture({{"scale",{0,1,1}}}));});auto truncated=fixture();truncated.pop_back();rejects([&]{im::readGLB(truncated);});require(std::abs(half(im::toHalf(.37))-.37)<.001,"Half writer round trip failed");std::cout<<"Synthetic GLB transforms, bounds, indices and half-floats passed\n";
 if(argc==4){Archive archive((fs::path(argv[1])/"vfs.zip").u8string());auto source=im::readGLB(read(argv[2]));auto candidates=im::donors(archive,source.bounds.size());require(candidates.size()>=10,"Donor coverage missing");size_t passed=0;for(auto&d:candidates){try{auto result=im::convert(source,im::stockAsset(archive,"graphics/vehicles/"+d.id+"/lod0_livery.bdae"),{});require(result.report.at("imported_triangles")==source.triangles,"Lost input triangles");std::cout<<"Converted "<<d.name<<" ("<<d.id<<")\n";passed++;}catch(const std::exception&e){std::cout<<"Rejected "<<d.name<<": "<<e.what()<<"\n";}}require(passed>0,"No donor converted");auto chosen=std::find_if(candidates.begin(),candidates.end(),[](auto&d){return d.id=="alf";});require(chosen!=candidates.end(),"Missing Pulse");im::exportModel(archive,source,*chosen,{},argv[3],"Imported Impala Test");ImportedMod mod(argv[3],&archive);require(mod.cars.count("alf"),"Export did not reimport");auto labels=displayNamesFrom([&](const std::string&p){return mod.assetBytes(p,archive);});require(localized(labels,"car_alf")=="Imported Impala Test","Name export failed");ModAppearance appearance(mod,archive,labels);require(!appearance.paints.empty(),"Paint editor cannot open export");auto original=im::stockAsset(archive,"graphics/vehicles/alf/collision.hzc");require(mod.assetBytes("graphics/vehicles/alf/collision.hzc",archive)==original,"Donor collision changed");rejects([&]{im::exportModel(archive,source,*chosen,{},argv[3],"duplicate");});std::cout<<"Export, reimport, name, paint editing and no-overwrite passed; "<<passed<<" donors converted\n";
 }
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
